select id, nome, descricao, composicao, desconto_percentual, ativo from jsonb_to_recordset($j$[{"id":"a6b1492c-6de6-9e53-7f02-af978abc6adb","nome":"Kit Brinde a Dois","descricao":"Duas taças de espumante com a mesma arte. Presente clássico de casamento e bodas.","composicao":[{"modelo_id":"d5650510-c27e-73a6-225f-04a0625262a0","quantidade":2}],"desconto_percentual":10,"ativo":true},{"id":"7eff6612-49bd-9ca3-d4e3-7efc855cbd55","nome":"Kit Padrinhos","descricao":"Duas taças Bordeaux e uma garrafa de vidro, tudo com a mesma pintura.","composicao":[{"modelo_id":"0a3aa814-a1ed-0324-28ab-903d57f41a26","quantidade":2},{"modelo_id":"071c66df-5428-5ba5-562a-9873e2c4f626","quantidade":1}],"desconto_percentual":12,"ativo":true},{"id":"3462102f-2e28-7b02-9ba6-05ab63dc5784","nome":"Kit Café da Manhã","descricao":"Duas canecas e duas xícaras com pires, combinando.","composicao":[{"modelo_id":"52d124c1-4844-daac-aa5d-d0934c9318da","quantidade":2},{"modelo_id":"59919ff0-5948-88c8-1a74-4f57364b68f8","quantidade":2}],"desconto_percentual":10,"ativo":true}]$j$::jsonb) as x(id uuid, nome text, descricao text, composicao jsonb, desconto_percentual numeric, ativo boolean)
